package com.codeoneditor.core.editor.syntax.languages

import com.codeoneditor.core.editor.model.FileType
import com.codeoneditor.core.editor.syntax.SyntaxLanguage

private fun words(value: String) = value.trimIndent().split(Regex("\\s+")).filter(String::isNotBlank).toSet()
private val cFamily = words("""
alignas alignof and and_eq asm auto bitand bitor break case catch char class compl const consteval constexpr constinit continue co_await co_return co_yield decltype default delete do double else enum explicit export extern false float for friend goto if inline int long mutable namespace new noexcept not nullptr operator or or_eq private protected public register reinterpret_cast requires return short signed sizeof static static_assert static_cast struct switch template this thread_local throw true try typedef typeid typename union unsigned using virtual void volatile wchar_t while xor xor_eq
""")
private val kotlin = words("""as break class continue do else false for fun if in interface is null object package return super this throw true try typealias typeof val var when while by catch constructor delegate dynamic field file finally get import init param property receiver set setparam where actual abstract annotation companion const crossinline data enum expect external final infix inline inner internal lateinit noinline open operator out override private protected public reified sealed suspend tailrec vararg""")
private val java = words("""abstract assert boolean break byte case catch char class const continue default do double else enum extends final finally float for goto if implements import instanceof int interface long native new package private protected public return short static strictfp super switch synchronized this throw throws transient try void volatile while true false null record sealed permits var yield""")
private val python = words("""and as assert async await break case class continue def del elif else except finally for from global if import in is lambda match nonlocal not or pass raise return try while with yield True False None""")
private val javascript = words("""as async await break case catch class const continue debugger default delete do else export extends finally for from function get if implements import in instanceof interface let new null of package private protected public return set static super switch this throw try typeof undefined var void while with yield true false enum arguments eval""")
private val typescript = javascript + words("""abstract any bigint boolean declare infer is keyof namespace never number object readonly require string symbol type unknown unique module constructor override satisfies asserts""")
private val rust = words("""as async await break const continue crate dyn else enum extern false fn for if impl in let loop match mod move mut pub ref return self Self static struct super trait true type unsafe use where while abstract macro override typeof yield try""")
private val go = words("""break default func interface select case defer go map struct chan else goto package switch const fallthrough if range type continue for import return var true false iota nil""")
private val csharp = words("""abstract as base bool break byte case catch char checked class const continue decimal default delegate do double else enum event explicit extern false finally fixed float for foreach goto if implicit in int interface internal is lock long namespace new null object operator out override params private protected public readonly ref return sbyte sealed short sizeof static string struct switch this throw true try typeof uint ulong unchecked unsafe ushort using virtual void volatile while async await dynamic var record""")
private val sql = words("""select from where insert into update delete merge create alter drop table view index database schema primary key foreign references unique check default constraint join inner left right full outer cross on as and or not null is in exists between like group by having order asc desc limit offset union all distinct case when then else end with recursive values set returning""")
private val shell = words("""if then else elif fi for while in do done case esac function select until time coproc return break continue export readonly local declare typeset unset source alias unalias true false""")
private val php = words("""abstract and array as break callable case catch class clone const continue declare default die do echo else elseif empty enddeclare endfor endforeach endif endswitch endwhile eval exit extends final finally fn for foreach function global goto if implements include include_once instanceof insteadof interface isset list match namespace new or print private protected public require require_once return static switch throw trait try unset use var while xor yield true false null""")
private val swift = words("""associatedtype class deinit enum extension fileprivate func import init inout internal let open operator private protocol public rethrows static struct subscript typealias var break case continue default defer do else fallthrough for guard if in repeat return switch where while as any catch false is nil super self Self throw throws true try async await actor nonisolated some consuming borrowing""")
private val dart = words("""abstract as assert async await break case catch class const continue covariant default deferred do dynamic else enum export extends extension external factory false final finally for Function get hide if implements import in interface is late library mixin new null on operator part required rethrow return set show static super switch sync this throw true try typedef var void while with yield""")
private val ruby = words("""BEGIN END alias and begin break case class def defined do else elsif end ensure false for if in module next nil not or redo rescue retry return self super then true undef unless until when while yield require include extend""")
private val scala = words("""abstract case catch class def do else extends false final finally for forSome if implicit import lazy match new null object override package private protected return sealed super this throw trait try true type val var while with yield given using enum extension opaque inline transparent""")
private val lua = words("""and break do else elseif end false for function goto if in local nil not or repeat return then true until while""")
private val genericTypes = words("""String Int Integer Long Short Byte Float Double Boolean Char Number Object Any AnyRef Unit Nothing List Map Set Array Collection Iterable Sequence Result Option Either Promise Future Error Exception i8 i16 i32 i64 i128 u8 u16 u32 u64 u128 f16 f32 f64 usize isize bool char str Vec""")
private val commonComments = listOf("//") to listOf("/*" to "*/")

fun definitionFor(type: FileType): SyntaxLanguage = when (type) {
    FileType.KOTLIN -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), kotlin, genericTypes)
    FileType.JAVA -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), java, genericTypes)
    FileType.PYTHON -> SyntaxLanguage(type, listOf("#"), keywords = python, types = genericTypes, hashComments = true)
    FileType.JAVASCRIPT, FileType.JSX -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), javascript, genericTypes)
    FileType.TYPESCRIPT, FileType.TSX -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), typescript, genericTypes)
    FileType.C, FileType.CPP -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), cFamily, genericTypes)
    FileType.CSHARP -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), csharp, genericTypes)
    FileType.RUST -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), rust, genericTypes)
    FileType.GO -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), go, genericTypes)
    FileType.PHP -> SyntaxLanguage(type, listOf("//", "#"), listOf("/*" to "*/"), php, genericTypes, hashComments = true)
    FileType.SWIFT, FileType.OBJECTIVE_C -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), swift, genericTypes)
    FileType.DART -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), dart, genericTypes)
    FileType.RUBY -> SyntaxLanguage(type, listOf("#"), listOf("=begin" to "=end"), ruby, hashComments = true)
    FileType.SCALA -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), scala, genericTypes)
    FileType.LUA -> SyntaxLanguage(type, listOf("--"), listOf("--[[" to "]]"), lua, genericTypes)
    FileType.R -> SyntaxLanguage(type, listOf("#"), keywords = words("if else repeat while function for in next break TRUE FALSE NULL Inf NaN"), hashComments = true)
    FileType.SQL -> SyntaxLanguage(type, listOf("--"), listOf("/*" to "*/"), sql, genericTypes, caseInsensitiveKeywords = true)
    FileType.BASH, FileType.SHELL -> SyntaxLanguage(type, listOf("#"), keywords = shell, hashComments = true)
    FileType.POWERSHELL -> SyntaxLanguage(type, listOf("#"), listOf("<#" to "#>"), shell, hashComments = true)
    FileType.HTML, FileType.XML -> SyntaxLanguage(type, blockComments = listOf("<!--" to "-->"), markup = true)
    FileType.CSS, FileType.SCSS, FileType.SASS, FileType.LESS -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), cssLike = true)
    FileType.JSON -> SyntaxLanguage(type, blockComments = listOf("/*" to "*/"), jsonLike = true)
    FileType.YAML, FileType.TOML, FileType.PROPERTIES, FileType.ENV, FileType.GITIGNORE -> SyntaxLanguage(type, listOf("#"), hashComments = true)
    FileType.MARKDOWN -> SyntaxLanguage(type, listOf("<!--"), listOf("<!--" to "-->"), markdown = true)
    FileType.GRADLE, FileType.GRADLE_KTS, FileType.GROOVY -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), java, genericTypes)
    FileType.CMAKE, FileType.MAKEFILE, FileType.PROGUARD -> SyntaxLanguage(type, listOf("#"), hashComments = true)
    FileType.GRAPHQL -> SyntaxLanguage(type, listOf("#"), keywords = words("query mutation subscription fragment on schema type interface union enum input directive scalar implements extend"), types = genericTypes)
    FileType.ASSEMBLY -> SyntaxLanguage(type, listOf(";", "#"), keywords = words("mov push pop call ret cmp jmp je jne jl jg add sub mul div inc dec lea nop and or xor not test"))
    FileType.ZIG, FileType.D, FileType.HLSL, FileType.GLSL, FileType.SHADERLAB -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), cFamily, genericTypes)
    FileType.FORTRAN -> SyntaxLanguage(type, listOf("!"), keywords = words("program module subroutine function end if then else do select case use implicit none integer real logical character type call return continue stop"), caseInsensitiveKeywords = true)
    FileType.SOLIDITY -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), words("pragma solidity contract interface library struct enum event function modifier constructor fallback receive mapping memory storage calldata public private internal external view pure payable returns return require revert assert if else for while new import using is"), genericTypes)
    FileType.MOVE -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), words("module script fun struct resource public entry use friend spec acquires let move copy abort assert if else while loop return"))
    FileType.HASKELL -> SyntaxLanguage(type, listOf("--"), listOf("{-" to "-}"), words("case class data default deriving do else foreign if import in infix let module newtype of then type where forall qualified hiding instance"), genericTypes)
    FileType.CLOJURE, FileType.LISP -> SyntaxLanguage(type, listOf(";"), keywords = words("def defn let if do fn loop recur quote var setq atom cons first rest map reduce ns require"))
    FileType.FSHARP -> SyntaxLanguage(type, listOf("//"), listOf("(*" to "*)"), words("let rec match with function type module namespace open member interface inherit abstract override if then else for while do done mutable async yield return"))
    FileType.OCAML -> SyntaxLanguage(type, blockComments = listOf("(*" to "*)"), keywords = words("let rec match with function type module open include if then else for while mutable class object method inherit"))
    FileType.PROLOG -> SyntaxLanguage(type, listOf("%"), listOf("/*" to "*/"), words(":- module use_module dynamic multifile discontiguous true false fail not"))
    FileType.DOCKERFILE -> SyntaxLanguage(type, listOf("#"), keywords = words("FROM RUN CMD LABEL MAINTAINER EXPOSE ENV ADD COPY ENTRYPOINT VOLUME USER WORKDIR ARG ONBUILD STOPSIGNAL HEALTHCHECK SHELL"))
    FileType.MATLAB -> SyntaxLanguage(type, listOf("%"), keywords = words("function end if else elseif for while switch case otherwise try catch return classdef properties methods events"))
    FileType.JULIA -> SyntaxLanguage(type, listOf("#"), listOf("#=" to "=#"), keywords = words("abstract type baremodule begin break catch const continue do else elseif end export finally for function global if import let local macro module mutable primitive quote return struct try using while where"))
    FileType.PERL, FileType.RAKU -> SyntaxLanguage(type, listOf("#"), keywords = words("my our sub package use require if elsif else unless while until for foreach given when default return next last redo die eval bless undef"))
    FileType.TCL -> SyntaxLanguage(type, listOf("#"), keywords = words("proc set if elseif else while for foreach switch namespace return break continue expr puts source package"))
    FileType.AWK -> SyntaxLanguage(type, listOf("#"), keywords = words("BEGIN END if else while for do function next nextfile print printf delete in getline"))
    FileType.GDSCRIPT -> SyntaxLanguage(type, listOf("#"), keywords = words("extends class_name func var const signal enum static if elif else for while match when return break continue pass await preload load"))
    else -> SyntaxLanguage(type, listOf("//"), listOf("/*" to "*/"), types = genericTypes)
}
